/**
 * The homepage crest band's one data source (V30, brief Parts 1–3).
 *
 * Every marquee item is a *university*, not an image with an optional link next to it: id (the national
 * register's `registry_id`), slug, official names, crest asset and the detail route all travel together, and
 * the detail route is derived from the slug in exactly one place. The manifest itself is generated by
 * `scripts/media/build_marquee_manifest.py` against the register, so a crest cannot name a slug that does
 * not exist there.
 *
 * A crest that lacks an id or a slug is **not rendered** — a logo with no university behind it is the
 * defect this module exists to make impossible. `qa:v30-marquee` asserts the filtered count still equals the
 * manifest count, so dropping one here is loud, never silent.
 */
import manifest from '../media/universities.json';

export interface UniversityMarqueeItem {
  /** National register id (대학알리미) — the university's identity, stable across renames. */
  id: string;
  slug: string;
  nameKo: string;
  nameEn: string;
  crest: { file: string; width: number; height: number; scale: number; tile: boolean };
  row: 1 | 2 | 3;
}

type ManifestRow = (typeof manifest)[number] & { tile?: boolean };

export const MARQUEE_UNIVERSITIES: readonly UniversityMarqueeItem[] = (manifest as ManifestRow[])
  .filter((c) => Boolean(c.registry_id && c.slug))
  .map((c) => ({
    id: c.registry_id,
    slug: c.slug,
    nameKo: c.name_ko,
    nameEn: c.name_en,
    crest: { file: c.file, width: c.width, height: c.height, scale: c.scale, tile: Boolean(c.tile) },
    row: c.row as 1 | 2 | 3,
  }));

/** The canonical detail route. Locale is added by `LocaleLink` (default `ko` carries no `?lang=`). */
export function universityPath(item: Pick<UniversityMarqueeItem, 'slug'>): string {
  return `/universities/${item.slug}`;
}

export function marqueeRows(): UniversityMarqueeItem[][] {
  return [1, 2, 3].map((r) => MARQUEE_UNIVERSITIES.filter((u) => u.row === r));
}
